with joined as (select e.*, b.amount as order_amount, b.discount from payments e left join orders b on e.order_id = b.id) select date_trunc('week', paid_at) as week_start, method, approx_percentile(order_amount, 0.9) as order_amount_p90, min(discount) as min_discount, count(*) as num_rows, count(case when status = 'SUCCESS' then 1 end) as success_count, sum(case when method = 'promptpay' then discount else 0 end) as promptpay_discount, count(*) filter (where method = 'paypal') as paypal_rows from joined group by date_trunc('week', paid_at), method;
